"""Static, non-executing inspector for untrusted pickle checkpoints.

Never hands the byte stream to the pickle VM. Instead it replays the opcode
stream structurally and *taints* any opcode that could execute code, so the
surrounding data can still be recovered safely.
"""
import io
import json
import pickletools
import sys


class Poison:
    """Stands in for a value that would have required code execution."""

    def __init__(self, desc):
        self.desc = desc

    def __repr__(self):
        return "<UNSAFE: %s>" % self.desc

    def __hash__(self):
        return hash(self.desc)

    def __eq__(self, other):
        return isinstance(other, Poison) and other.desc == self.desc


class _Mark:
    __slots__ = ()


MARK = _Mark()

# Opcodes that can invoke arbitrary code or pull in outside objects.
UNSAFE = {
    "GLOBAL", "STACK_GLOBAL", "REDUCE", "INST", "OBJ", "NEWOBJ", "NEWOBJ_EX",
    "BUILD", "PERSID", "BINPERSID", "EXT1", "EXT2", "EXT4", "META",
}


def _pop_to_mark(stack):
    items = []
    while stack:
        top = stack.pop()
        if top is MARK:
            return list(reversed(items))
        items.append(top)
    raise ValueError("MARK not found on stack")


def inspect(data: bytes):
    """Replay opcodes structurally. Returns (object, findings)."""
    stack = []
    memo = {}
    findings = []
    stop_value = None

    for op, arg, pos in pickletools.genops(io.BytesIO(data)):
        name = op.name

        if name in UNSAFE:
            if name in ("GLOBAL", "STACK_GLOBAL"):
                if name == "GLOBAL":
                    target = "%s.%s" % (arg[0], arg[1])
                else:
                    mod = stack.pop()
                    fn = stack.pop()
                    target = "%s.%s" % (mod, fn)
                findings.append({"offset": pos, "opcode": name, "target": target})
                stack.append(Poison("global lookup of %s" % target))
            elif name == "REDUCE":
                args = stack.pop()
                callee = stack.pop()
                findings.append({
                    "offset": pos, "opcode": name,
                    "target": repr(callee), "args": repr(args),
                })
                stack.append(Poison("REDUCE calling %s with %r" % (callee, args)))
            else:
                findings.append({"offset": pos, "opcode": name, "args": repr(arg)})
                # Consume whatever operands the opcode would have taken.
                if name in ("PERSID",):
                    pass
                elif name in ("BINPERSID", "EXT1", "EXT2", "EXT4"):
                    stack.pop()
                elif name in ("INST", "OBJ"):
                    _pop_to_mark(stack)
                    stack.pop()
                elif name == "NEWOBJ":
                    stack.pop(); stack.pop()
                elif name == "NEWOBJ_EX":
                    stack.pop(); stack.pop(); stack.pop()
                elif name == "BUILD":
                    stack.pop()
                stack.append(Poison("opcode %s" % name))
            continue

        if name == "STOP":
            stop_value = stack[-1] if stack else None
            break

        if name in ("PROTO", "FRAME"):
            continue
        if name in ("MEMOIZE",):
            memo[len(memo)] = stack[-1]
            continue
        if name in ("PUT", "BINPUT", "LONG_BINPUT"):
            memo[arg] = stack[-1]
            continue
        if name in ("GET", "BINGET", "LONG_BINGET"):
            stack.append(memo.get(arg))
            continue
        if name in ("NONE",):
            stack.append(None); continue
        if name == "NEWTRUE":
            stack.append(True); continue
        if name == "NEWFALSE":
            stack.append(False); continue
        if name in ("SHORT_BINUNICODE", "BINUNICODE", "UNICODE", "BINSTRING",
                    "STRING", "SHORT_BINSTRING", "SHORT_BINUNICODE8",
                    "BINUNICODE8"):
            stack.append(arg); continue
        if name in ("BININT", "BININT1", "BININT2", "LONG1", "LONG4", "INT",
                    "LONG", "BINFLOAT", "FLOAT", "BINBYTES", "SHORT_BINBYTES",
                    "BINBYTES8", "BYTEARRAY8", "NEXT_BUFFER", "READONLY_BUFFER"):
            stack.append(arg); continue
        if name in ("EMPTY_DICT", "DICT"):
            stack.append({}); continue
        if name in ("EMPTY_LIST", "LIST"):
            if name == "LIST":
                stack.append(_pop_to_mark(stack))
            else:
                stack.append([])
            continue
        if name in ("EMPTY_SET", "EMPTY_TUPLE"):
            stack.append(set() if name == "EMPTY_SET" else ()); continue
        if name == "MARK":
            stack.append(MARK); continue
        if name in ("TUPLE1", "TUPLE2", "TUPLE3"):
            n = int(name[-1])
            items = [stack.pop() for _ in range(n)]
            stack.append(tuple(reversed(items))); continue
        if name == "TUPLE":
            stack.append(tuple(_pop_to_mark(stack))); continue
        if name == "FROZENSET":
            stack.append(frozenset(_pop_to_mark(stack))); continue
        if name == "APPEND":
            stack[-1].append(stack.pop()); continue
        if name == "APPENDS":
            stack[-1].extend(_pop_to_mark(stack)); continue
        if name == "ADDITEMS":
            stack[-1].update(_pop_to_mark(stack)); continue
        if name == "SETITEM":
            v = stack.pop(); k = stack.pop()
            stack[-1][k] = v; continue
        if name == "SETITEMS":
            items = _pop_to_mark(stack)
            for k, v in zip(items[0::2], items[1::2]):
                stack[-1][k] = v
            continue
        if name == "DUP":
            stack.append(stack[-1]); continue
        if name == "POP":
            stack.pop(); continue
        if name == "POP_MARK":
            _pop_to_mark(stack); continue
        if name in ("SETITEMS_MARK", "APPENDS_MARK"):
            continue

        raise ValueError("unhandled opcode %r at offset %d" % (name, pos))

    return stop_value, findings


def main():
    path = sys.argv[1]
    with open(path, "rb") as fh:
        data = fh.read()

    obj, findings = inspect(data)

    print("== file: %s (%d bytes) ==" % (path, len(data)))
    if findings:
        print("\n!! UNSAFE OPCODES DETECTED -- payload NOT executed !!")
        for f in findings:
            print("   offset %-4d %-13s %s" % (
                f["offset"], f["opcode"], f.get("target", "")))
            if f.get("args"):
                print("        args: %s" % f["args"])
    else:
        print("\nno code-execution opcodes found")

    print("\n== top-level keys ==")
    if isinstance(obj, dict):
        for k, v in obj.items():
            tag = "  <-- UNSAFE" if isinstance(v, Poison) else ""
            print("   %-20s %s%s" % (k, type(v).__name__, tag))

    print("\n== recoverable inventory ==")
    inv = {
        "model_type": obj["model_type"],
        "protocol_version": obj["protocol_version"],
        "tensors": list(obj["tensors"].keys()),
    }
    print(json.dumps(inv, indent=2))

    with open("/tmp/safeintake/inventory.json", "w") as fh:
        json.dump(inv, fh, indent=2)
    return 0


if __name__ == "__main__":
    sys.exit(main())
